import { createTestContext, FluentXmlFluentTest, XmlFluentXmlTest } from '../test-utils'
import { Diagnostic, FluentDiagnostic, path } from '@servicenow/sdk-build-core'

describe('NowIncludePlugin tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    test('on build, it can inline the text from a JS file into a field', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })
        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('./my_test_script.js')
    }
})
`,
        })

        const diagnostics = (await nowTsFile.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await nowTsFile.getRecords()).query()
        expect(record?.get('script').getValue()).toEqual('// My Code!')
    })

    test('on build, it can inline the text from a JS file into a field (using a const)', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })
        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

const script = Now.include('./my_test_script.js')

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: script,
    }
})
`,
        })

        const diagnostics = (await nowTsFile.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await nowTsFile.getRecords()).query()
        expect(record?.get('script').getValue()).toEqual('// My Code!')
    })

    test('on build, it can inline the text from an HTML file into a field', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const recordId = project.registerExplicitId('hello_ui', 'hello')

        project.addFile({ path: 'src/ui/hello.html', content: '<h1>Hello</h1>' })
        const fluentFile = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['hello'],
    table: 'hello_ui',
    data: {
        html: Now.include('../ui/hello.html'),
    }
})
`,
        })

        expect((await fluentFile.getDiagnostics()).map((d) => d.message)).toEqual([])
        expect(
            (await fluentFile.getOutput()).find((f) => f.path.endsWith(`hello_ui_${recordId}.xml`))?.content
        ).toEqual(`<?xml version="1.0"?>
<record_update table="hello_ui">
  <hello_ui action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <sys_update_name>hello_ui_${recordId}</sys_update_name>
    <html><![CDATA[<h1>Hello</h1>]]></html>
  </hello_ui>
</record_update>`)
    })

    test('on build, inline script from file in same directory with no directory specifier in path', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })
        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('my_test_script.js')
    }
})
`,
        })

        const diagnostics = (await nowTsFile.getDiagnostics()).map((d) => d.message)
        expect(diagnostics).toEqual([])

        const [record] = (await nowTsFile.getRecords()).query()
        expect(record?.get('script').getValue()).toEqual('// My Code!')
    })

    test('reports a diagnostic if the file cannot be found', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('./does_not_exist.js')
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toMatch('Failed to include file. Reason: No file found at path:')
    })

    test('reports a diagnostic if the file exists outside the project', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const outsideFile = `../somewhere/outsideFile.js`

        project.addFile({ path: outsideFile, content: '// This script it outside the project' })
        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('../../${outsideFile}')
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toMatch('Included file path is not within project:')
    })

    test('reports a diagnostic if the value is not a string literal', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })

        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

const script = Now.include(123)

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script,
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toBe('Now.include() must have a string argument')
    })

    test('reports a diagnostic if the filepath is empty', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })

        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include(''),
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toMatch('Failed to include file. Reason: No file found at path:')
    })

    test('reports a diagnostic if the filepath is empty', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })

        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include(''),
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toMatch('Failed to include file. Reason: No file found at path:')
    })

    test('reports a diagnostic if the filepath is a directory', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        project.addFile({ path: 'src/fluent/my_test_script.js', content: '// My Code!' })

        const nowTsFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('../..'),
    }
})
`,
        })

        const [diagnostic] = (await nowTsFile.getDiagnostics()).filter((d) => d instanceof FluentDiagnostic)
        expect(diagnostic?.message).toMatch('Failed to include file. Reason: Cannot add directory as file:')
    })

    test('sync an included file with no changes', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const recordId = project.registerExplicitId('sys_script', 'hello')

        const scriptFile = project.addFile({ path: 'src/scripts/hello.js', content: '// My Code!' })
        const fluentFile = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

const script = Now.include('../scripts/hello.js')

Record({
    $id: Now.ID['hello'],
    table: 'sys_script',
    data: {
        name: 'Hello',
        collection: 'incident',
        script: script,
    }
})
`,
        })

        expect(
            // Will have hints because we're creating a business rule with a Record() call, so just filter down to errors
            (await fluentFile.getDiagnostics())
                .filter((d) => d.level === Diagnostic.Level.Error)
                .map((d) => d.message)
        ).toEqual([])

        const originalScriptCode = scriptFile.getContent()
        const originalFluentCode = fluentFile.getContent()

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <sys_script action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <name>Hello</name>
    <script><![CDATA[// My Code!]]></script>
  </sys_script>
</record_update>`,
        })

        expect(fluentFile.getContent()).toEqual(originalFluentCode)
        expect(scriptFile.getContent()).toEqual(originalScriptCode)
        expect(changedFiles).toHaveLength(0)
    })

    test('sync an included file with changes to the file content', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const recordId = project.registerExplicitId('sys_script', 'hello')

        const scriptFile = project.addFile({ path: 'src/scripts/hello.js', content: '// My Code!' })
        const fluentFile = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

const script = Now.include('../scripts/hello.js')

Record({
    $id: Now.ID['hello'],
    table: 'sys_script',
    data: {
        name: 'Hello',
        collection: 'incident',
        script: script,
    }
})
`,
        })

        expect(
            // Will have hints because we're creating a business rule with a Record() call, so just filter down to errors
            (await fluentFile.getDiagnostics())
                .filter((d) => d.level === Diagnostic.Level.Error)
                .map((d) => d.message)
        ).toEqual([])

        const originalFluentCode = fluentFile.getContent()

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <sys_script action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <name>Hello</name>
    <script><![CDATA[gs.info("Hello!")]]></script>
  </sys_script>
</record_update>`,
        })

        expect(fluentFile.getContent()).toEqual(originalFluentCode)
        expect(changedFiles[0].getPath()).toBe(scriptFile.getPath())
        expect(changedFiles[0].getContent()).toBe("gs.info('Hello!')\n")
        expect(changedFiles).toHaveLength(1)
    })

    test('sync an included HTML file with changes to the file content', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const recordId = project.registerExplicitId('hello_ui', 'hello')

        const htmlFile = project.addFile({ path: 'src/ui/hello.html', content: '<h1>Hello</h1>' })
        const fluentFile = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['hello'],
    table: 'hello_ui',
    data: {
        html: Now.include('../ui/hello.html'),
    }
})
`,
        })

        expect((await fluentFile.getDiagnostics()).map((d) => d.message)).toEqual([])

        const originalFluentCode = fluentFile.getContent()

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <hello_ui action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <html><![CDATA[<h1>Goodbye!</h1>]]></html>
  </hello_ui>
</record_update>`,
        })

        expect(fluentFile.getContent()).toEqual(originalFluentCode)
        expect(changedFiles[0].getPath()).toBe(htmlFile.getPath())
        expect(changedFiles[0].getContent()).toBe('<h1>Goodbye!</h1>')
        expect(changedFiles).toHaveLength(1)
    })

    test('sync an empty file with changes to the file content', async () => {
        const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
        const recordId = project.registerExplicitId('hello_ui', 'hello')

        const htmlFile = project.addFile({ path: 'src/ui/hello.txt', content: '' })
        const fluentFile = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['hello'],
    table: 'hello_ui',
    data: {
        text: Now.include('../ui/hello.txt'),
    }
})
`,
        })

        expect((await fluentFile.getDiagnostics()).map((d) => d.message)).toEqual([])

        const originalFluentCode = fluentFile.getContent()

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <hello_ui action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <text><![CDATA[Hello World!]]></text>
  </hello_ui>
</record_update>`,
        })

        expect(fluentFile.getContent()).toEqual(originalFluentCode)
        expect(changedFiles[0].getPath()).toBe(htmlFile.getPath())
        expect(changedFiles[0].getContent()).toBe('Hello World!')
        expect(changedFiles).toHaveLength(1)
    })

    describe('Fluent => XML => Fluent', () => {
        test('file round-trips correctly', async () => {
            const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })

            const roundTripTest = new FluentXmlFluentTest(project)

            project.addFile({ path: 'my_test_script.js', content: '// My Code!' })
            const id = roundTripTest.addId('test_table', 'test')
            roundTripTest.addExpectedXmlFileNames(`test_table_${id}.xml`)

            roundTripTest.addFluentFragment(
                `
import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['test'],
    table: 'test_table',
    data: {
        name: 'Name',
        script: Now.include('./my_test_script.js')
    }
})
`
            )

            await roundTripTest.verify()
        })
    })

    describe('XML => Fluent => XML', () => {
        test('ACL with roles round-trips correctly', async () => {
            const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
            const recordId = project.registerExplicitId('hello_ui', 'hello')

            const originalFiles = [
                {
                    path: `hello_ui_${recordId}.xml`,
                    content: `<?xml version="1.0"?>
<record_update>
  <hello_ui action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <html>&lt;h1&gt;Goodbye!&lt;/h1&gt;</html>
  </hello_ui>
</record_update>`,
                },
            ]
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
})
